P = [
 dict(pmid='43027972', doi='10.3390/ijms27219724', journal='Int J Mol Sci', title='Colon Effects of 7-Day Whole-Body Inhalation Exposure of Fischer 344 Rats to Emissions from First- and Second-Generation Biodiesel Fuels with and Without a Particle Filter.', short='Warsaw Fischer 344 rats 7-day whole-body biodiesel exhaust B7 SHB20 DPF colon oxidative stress', design='Animal inhalation experiment', pm='Diesel engine exhaust from B7 and SHB20 biofuels, measured PM 2.13-2.19 mg/m3 without and 0.17-0.19 mg/m3 with DPF', geo='Poland (laboratory)', endpoint='Colon lipid peroxidation, redox and antioxidant markers, inflammation', tier='B', basis='Lab / research instrument', affil='Warsaw University of Life Sciences, Poland; Institute of Nuclear Chemistry and Technology, Poland', n='Male Fischer 344 rats breathed whole-body diesel exhaust from first-generation B7 or second-generation SHB20 (FAME plus hydrotreated vegetable oil) blends for 7 days, 6 h/day, at measured PM of 2.19 and 2.13 mg/m3 without a particle filter and 0.17 and 0.19 mg/m3 with one. Exhaust induced colonic lipid peroxidation, redox shifts, antioxidant mobilisation and inflammation-associated responses; effects were blend-specific, strongest for SHB20 without DPF, and only partly mitigated by the filter. Doses are two to three orders above ambient, exposure is the whole mixture (NOx and VOCs included), and the abstract gives no effect sizes or group sizes. Relevance: indirect - the DPF arm cuts PM about 12-fold without abolishing effects, pointing at the gas phase or ultrafines that mass-based sensors do not see.', sub=corpus.MECH),
 dict(pmid='43027370', doi='10.3390/cells15212013', journal='Cells', title='Worse than the Insult: The Role of Macrophages and Lymphocytes in Organic Dust-Induced Chronic Bronchitis.', short='NC A&T review organic dust livestock chronic bronchitis macrophages lymphocytes TLR4 NF-kB 18 studies', design='Narrative review', pm='Organic dust and its components (e.g. LPS) in livestock production', geo='Global (review)', endpoint='Macrophage and lymphocyte activation in organic dust-associated chronic bronchitis', tier='C', basis='Review / no primary exposure', affil='North Carolina A&T State University, USA; North Carolina A&T State University, USA', n='Review of the cellular basis of chronic bronchitis from livestock organic dust: 25,488 database hits narrowed to 18 research articles (2015-2025). Repetitive dust or LPS exposure keeps macrophages and lymphocytes activated through TLR4, TLR2, NF-kB, PKC, ERK and MAPK signalling, sustaining cytokine and chemokine output that drives mucus hypersecretion and airway remodelling; micronutrient or anti-inflammatory co-treatment blunted inflammation in experimental work. The selection from 25,488 hits to 18 papers is not described with a reproducible protocol, no exposure-response information is extracted, and dust is characterised by source rather than size or mass. Relevance: indirect - agricultural dust is a coarse, bioactive fraction that optical low-cost sensors size poorly; no measurement content.', sub=corpus.OCC),
 dict(pmid='43027053', doi='10.3390/biology15212042', journal='Biology (Basel)', title='Comparative Susceptibility to PM2.5-Induced Pulmonary Pathology: A Lifespan-Based Perspective on Animal Models.', short='Chiang Mai veterinary review PM2.5 lung pathology short vs long lifespan animal models One Health sentinel', design='Narrative review', pm='PM2.5 in laboratory rodents versus long-lived animals breathing ambient air', geo='Global (review)', endpoint='Pulmonary phenotype by lifespan: acute reversible injury versus chronic remodelling and neoplasia', tier='C', basis='Review / no primary exposure', affil='Chiang Mai University, Thailand; Chiang Mai University, Thailand', n='Review contrasting PM2.5 lung disease in short-lifespan laboratory rodents, typically dosed high for a small fraction of life, with long-lived species breathing ambient air for decades. Rodents show acute, often reversible inflammation; long-lived animals show cumulative particle bioaccumulation, airway remodelling and spontaneous neoplasia. The authors concede lifespan is confounded with exposure intensity and duration and cannot be separated from them, and propose veterinary sentinel cohorts, cross-species dosimetric scaling and in-tissue particle burden measurement. No systematic search or quantitative synthesis. Relevance: indirect - sentinel-animal cohorts would need long, spatially resolved ambient exposure records, the kind dense low-cost networks can supply.', sub=corpus.MECH),
 dict(pmid='43025325', doi='10.1016/j.jhazmat.2026.144171', journal='J Hazard Mater', title='Thermally driven aerosol dynamics and ultrafine particle emissions during electric stove heating.', short='Penn State Soongsil electric stove hot plate ceramic pan UFP 5.08e6 cm-3 coagulation source strength decay', design='Source-isolated emission test', pm='Size-resolved ultrafine particle number during electric-stove heating at 250 and 540 C', geo='USA (laboratory)', endpoint='Peak UFP number, source strength, size distribution, loss processes', tier='B', basis='Lab / research instrument', affil='Soongsil University, Republic of Korea; Pennsylvania State University, USA', n='Chamber-style tests of six electric-stove surface configurations at controller settings of 250 and 540 C, followed by decay. With no pan, total UFP reached 2.53 x 10^6 cm-3 at 250 C and 5.08 x 10^6 cm-3 at 540 C; repeated heating cut peaks by up to 91%. At 540 C the bare hot plate and a ceramic-coated pan emitted 5.47 x 10^12 and 4.89 x 10^12 particles/min in their first episodes, mostly in the smallest sizes; cookware shifted the distribution by material. Coagulation removed over 60% of early particles; deposition and ventilation dominated later, and a well-mixed model underpredicted measured concentrations. No food was cooked, so these are heater/cookware emissions only; single test space. Relevance: direct for indoor sensing - these particles are below the detection range of optical low-cost sensors, which will report a clean kitchen.', sub=corpus.OCC),
]
